import binary;

fn chunk_length(png: const u8[:], at: i64) -> u32, bool {
    let field, ok = binary::read_bytes(png, at, 4);
    if !ok { return 0, false; }
    var v: u32 = 0;
    for b in field { v = v << 8 | b; }
    return v, true;
}

fn main() {
    var png: u8[>..] = [];
    for b in [137, 80, 78, 71, 13, 10, 26, 10, 0, 0, 0, 13, 73, 72, 68, 82] { png.push(b as u8); }
    let len, ok = chunk_length(png, 8);
    let wrong, _ = binary::read_u32le(png, 8);
    print(len, " ", ok, " ", wrong);
}
```

